			projectedInputs.forEach((projection, values) -> {
				Extension extension = new Extension(projection.getArg());
				values.forEach(
						(name, value) -> extension.addElement(new ExtensionElem(new ValueConstant(value), name)));
				projection.setArg(extension);
			});
